<script setup>
import {ref,computed,watch} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {api} from '../lib/api';import {notice} from '../lib/state';import {num,pct,obraPath} from '../lib/format';import StatTile from '../components/StatTile.vue';import DataChart from '../components/DataChart.vue';import PageCard from '../components/PageCard.vue';
const route=useRoute(),data=ref(null),error=ref(''),active=ref('actividades'),editor=ref({}),saving=ref(false);
const base=computed(()=>`/obras/${route.params.obraId}`);
async function load(){try{data.value=await api.get(base.value+'/avance');if(data.value.curves?.length&&active.value!=='actividades'&&!data.value.curves.some(c=>c.key===active.value))active.value=data.value.curves[0].key}catch(e){error.value=e.message}}
watch(()=>route.params.obraId,load,{immediate:true});
function editPoint(curve,p){active.value=curve.key;editor.value={...p.inputs,semana:p.semana,curva:curve.key};}
function newPoint(curve){active.value=curve.key;editor.value={curva:curve.key,semana:curve.new_week,fecha:new Date().toISOString().slice(0,10),programado:'',real:'',reprogramado:''};}
async function save(){saving.value=true;try{await api.post(base.value+'/avance/curvas/'+editor.value.curva+'/puntos',editor.value);notice('Avance guardado');await load();editor.value={}}catch(e){error.value=e.message}finally{saving.value=false}}
</script>
<template><div class="page-heading page-heading--module"><div class="page-heading__titles"><h2 class="page-title display">Avance de obra</h2><p class="page-description">Curvas S programada, real y avance por actividad</p></div></div><p v-if="error" class="notice bad">{{error}}</p><template v-if="data"><nav class="pills tabs"><button class="pill" :aria-selected="active==='actividades'" @click="active='actividades'">Actividades</button><button v-for="c in data.curves" :key="c.key" class="pill" :aria-selected="active===c.key" @click="active=c.key">{{c.name}}</button></nav>
<template v-if="active==='actividades'"><div class="stat-grid cols-4"><StatTile label="Avance ponderado real" :value="pct(data.weighted?.real)"/><StatTile label="Programado" :value="pct(data.weighted?.programado)"/><StatTile label="Variación" :value="pct(data.weighted?.variacion)"/><StatTile label="Actividades" :value="num(data.activities?.length)"/></div><PageCard title="Actividades de obra"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Descripción</th><th>Estado</th><th>Programado</th><th>Real</th><th></th></tr></thead><tbody><tr v-for="r in data.activities" :key="r.obj.id"><td :style="{paddingLeft:(r.depth*14)+'px'}">{{r.obj.descripcion}}</td><td>{{r.obj.status||'—'}}</td><td>{{num(r.programado,1)}} %</td><td>{{num(r.real,1)}} %</td><td><RouterLink :to="obraPath(route.params.obraId,'actividad')+'/'+r.obj.id" class="btn btn-sm">Editar</RouterLink></td></tr></tbody></table></div></PageCard></template>
<template v-for="c in data.curves" :key="c.key"><div v-if="active===c.key"><div class="stat-grid cols-4"><StatTile label="Real" :value="pct(c.state?.real)" focal/><StatTile label="Programado" :value="pct(c.state?.programado)"/><StatTile label="Desvío" :value="c.delay"/><StatTile label="SPI" :value="c.spi"/></div><PageCard :title="c.title" :description="c.description"><DataChart :data="c.chart"/><template #actions><button v-if="data.editable" class="btn btn-primary" @click="newPoint(c)">+ Registrar avance</button></template></PageCard><PageCard title="Avance semanal"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Semana</th><th>Fecha</th><th>Programado</th><th>Real</th><th>Variación</th><th></th></tr></thead><tbody><tr v-for="p in c.points" :key="p.id"><td>{{p.semana}}</td><td>{{p.fecha}}</td><td>{{pct(p.programado)}}</td><td>{{pct(p.real)}}</td><td>{{p.variation}}</td><td><button v-if="data.editable" class="btn btn-sm" @click="editPoint(c,p)">Editar</button></td></tr></tbody></table></div></PageCard><PageCard v-if="editor.curva===c.key" title="Registrar avance"><form class="form-grid" @submit.prevent="save"><div v-for="[key,label] in [['semana','Semana'],['fecha','Fecha'],['programado','Programado (%)'],['real','Real (%)'],['reprogramado','Reprogramado (%)']]" :key="key" class="field"><label :for="key">{{label}}</label><input :id="key" v-model="editor[key]" :type="key==='fecha'?'date':'number'" :step="key==='semana'?'1':'any'" :required="key==='semana'||key==='fecha'"/></div><div class="form-actions"><button class="btn btn-primary" :disabled="saving">Guardar avance</button></div></form></PageCard></div></template></template></template>
